commands.command:
set -euo pipefail
python3 - <<'PY'
import json, pathlib, re, subprocess
home = pathlib.Path.home()
registry = home / 'Library/Application Support/local-agent/repositories.json'
print('=== REGISTRY ===')
raw = json.loads(registry.read_text())
for item in raw.get('repositories', []):
    print(json.dumps({k:item.get(k) for k in ('repository_id','repository','work_path','control_path','control_branch','default_branch','enabled')}, sort_keys=True))
print('=== SUPERVISOR ===')
try:
    out = subprocess.check_output(['ps','-p','71830','-o','command='], text=True).strip()
    print(out)
except Exception as exc:
    print('SUPERVISOR_READ_ERROR=' + repr(exc))
print('=== CHAT_BRIDGE_STORAGE ===')
chrome_root = home / 'Library/Application Support/Google/Chrome'
profiles = []
if chrome_root.exists():
    for p in chrome_root.iterdir():
        if p.is_dir() and (p.name == 'Default' or p.name.startswith('Profile ')):
            profiles.append(p)
found = 0
for profile in sorted(profiles):
    ext_root = profile / 'Extensions'
    if not ext_root.exists():
        continue
    for ext_dir in ext_root.iterdir():
        if not ext_dir.is_dir():
            continue
        manifests = sorted(ext_dir.glob('*/manifest.json'))
        for manifest in reversed(manifests):
            try:
                data = json.loads(manifest.read_text())
            except Exception:
                continue
            if data.get('name') != 'Local Agent Chat Bridge':
                continue
            found += 1
            ext_id = ext_dir.name
            print(f'PROFILE={profile.name} EXTENSION_ID={ext_id} VERSION={data.get("version")}')
            storage = profile / 'Local Extension Settings' / ext_id
            if not storage.exists():
                print('STORAGE=missing')
                continue
            hits = []
            for f in sorted(storage.iterdir()):
                if not f.is_file():
                    continue
                try:
                    blob = f.read_bytes()
                except Exception:
                    continue
                for run in re.findall(rb'[\x20-\x7e]{24,}', blob):
                    if b'bridgeState' in run or b'repositoryId' in run or b'conversations' in run:
                        text = run.decode('utf-8', errors='replace')
                        if text not in hits:
                            hits.append(text)
            if not hits:
                print('BRIDGE_STATE_PRINTABLE_HITS=0')
            else:
                print(f'BRIDGE_STATE_PRINTABLE_HITS={len(hits)}')
                for idx, text in enumerate(hits[:20], 1):
                    print(f'HIT[{idx}]={text[:12000]}')
            break
if not found:
    print('CHAT_BRIDGE_EXTENSION_NOT_FOUND')
PY

